create type public.app_role as enum ('admin');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role public.app_role not null, unique(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create function public.has_role(_user_id uuid, _role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
create policy own_roles on public.user_roles for select to authenticated using(user_id=auth.uid());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, description text not null default '', position integer not null default 0);
grant select on public.categories to anon; grant select,insert,update,delete on public.categories to authenticated; grant all on public.categories to service_role;
alter table public.categories enable row level security;
create policy category_read on public.categories for select using(true);
create policy category_admin on public.categories for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.products (id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, author text not null, cover text not null default '', price numeric(10,2) not null check(price>=0), category_id uuid references public.categories(id) on delete set null, description text not null default '', sample text not null default '', formats text[] not null default '{PDF}', pages integer not null default 0 check(pages>=0), published boolean not null default false, created_at timestamptz not null default now());
grant select on public.products to anon; grant select,insert,update,delete on public.products to authenticated; grant all on public.products to service_role;
alter table public.products enable row level security;
create policy public_products on public.products for select using(published);
create policy admin_products on public.products for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.product_files (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, path text not null, filename text not null);
grant select,insert,update,delete on public.product_files to authenticated; grant all on public.product_files to service_role;
alter table public.product_files enable row level security;
create policy admin_files on public.product_files for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.store_settings (id integer primary key check(id=1), announcement text not null default '', intro text not null default '', email text not null default '', phone text not null default '', address text not null default '', about text not null default '', privacy text not null default '', terms text not null default '', refund text not null default '', cookies text not null default '', dmca text not null default '', delivery text not null default '');
grant select on public.store_settings to anon; grant select,insert,update,delete on public.store_settings to authenticated; grant all on public.store_settings to service_role;
alter table public.store_settings enable row level security;
create policy settings_read on public.store_settings for select using(true);
create policy settings_admin on public.store_settings for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));